import{p as W}from"./plans-C9C6uQb6.js";import{B as u,i as k,ay as C,ab as X,az as Z,h as J,d as P,aa as H,k as y,aA as ee,aB as ae,aC as V,aD as oe,e as te}from"./index-JP3CJ4D2.js";const $e={width:1200,height:630},ie={default:"a8b87f2b4dbe",pricing:"f0bd6968da13","marble-race":"e24231f70714","fruit-merge":"3a1718abfab1","musical-path":"91e1ebbf4f65","shape-merger":"43e899f6c784","roll-hopper":"f2aeae42bbbd","pressure-clash":"91bbde5b557b","eureka-lab":"3e6995524cb8","melody-bounce":"60c2ded0a3d6","shatter-stack":"563d847a0166","perfect-swish":"d7f39c482f5d","chomp-tank":"2c291127302f","pocket-slam":"81651669084d","marble-machine":"b1d74397fa9a","glass-gauntlet":"276c0413df09","chaos-cutter":"35b6c49e2e01","blob-escape":"0016efd3d9cf","ball-slide":"f868c814777c","line-arena":"5160adb5500c"},se={default:"39be661b30e8",pricing:"f432ff119ac8","marble-race":"53f690889cae","fruit-merge":"43c24a19e5ba","musical-path":"d765fbbd2963","shape-merger":"c9c5359b6679","roll-hopper":"426141d1c8df","pressure-clash":"d3aae6f5f18e","eureka-lab":"83ecc8d3c763","melody-bounce":"ea4f4890235b","shatter-stack":"a7d6dc851c82","perfect-swish":"6eb48f37cec5","chomp-tank":"35e752554f09","pocket-slam":"c1820db1eb40","marble-machine":"e24338093dea","glass-gauntlet":"37cd6b5112b9","chaos-cutter":"1829327ad060","blob-escape":"b9af822809f6","ball-slide":"a7436ca59570","line-arena":"cb70bcff03fa","flag-atlas":"3d606c01ed2d","sort-spectrum":"296562ad7d44","algo-arena":"ed248651fab3","rising-tide":"5995a40048f8","pulse-bloom":"b99315a5eaf1","spin-loop":"e7657f940795","chime-chamber":"dbe54fb3865d","brawl-royale":"1be3c37d4456","bounce-chute":"f294c8e31c98","brick-build":"2f20d44a8584","neon-doubler":"b104c4c6d8b0","stick-race":"55b2059cc217","silhouette-fill":"83246c31ddaa","ring-escape":"2b14d201ee32","field-plough":"e774cc559e4a","iso-ball-wave":"e329466f1cb3","polygon-arena":"44f9a6ed54aa","bounce-fill":"f29505f52c4b","corner-wheel":"1963b7d2f465","pistol-duel":"41d47321ffa9","blueprint-builder":"ccd6d7550577","beat-ball":"4679a887d19c","bouncing-ball-arena":"664017b6fa7f","voxel-builder":"af50aaf37a7b","egg-simulation":"817ccc45dc96","ball-barrier-race":"0d0cc24a0ab8","tiny-trials":"e5638c3789b5","gate-rush":"5e3cce8f1c20","note-dial":"ec4e0bb9f20c","orbit-notes":"b6329c723494","score-sparks":"16cab77ab2b5","bounce-jukebox":"bccedeafe5a4","wobble-stack":"e506346e238d","crush-machine":"83d895916256","digit-duel":"3e6f101f4e62","every-bounce":"c02b68311b3b","star-beats":"e5785ed4bf62","beat-press":"4991f581ba3e","phase-loop":"170aa9973f19","sync-fountain":"668a82e68d51","hive-burst":"70c08b464b33","stair-sonata":"3d5d1a62709b","formula-towers":"d914985ecb63","fold-fractal":"88e27ef00bc0","fold-groove":"474c000511c0","piano-rain":"d62bd2bbb95c","ribbon-fold":"9e16067f10f3","spiral-shatter":"01f751fbdce6","ricochet-rally":"9e4de37a176f","tipping-point":"fa5648a1f26f"},I="Only use music you have the rights to use.",re={"piano-rain":{description:"Make piano visualizer videos: notes fall as bars of light onto the keys while rigged 3D hands play them. Pick a classic or a MIDI file. Record 9:16.",intro:"A piano that plays itself: every note falls as a bar of light and strikes its key exactly when it sounds, while rigged 3D hands finger every note. Pick a public-domain classic or an original, or load your own MIDI file with every track and both hands, then choose the view, key range, note style and colours.",ideas:["Load your own MIDI file and turn a piece you know into a falling-notes piano video.","Switch the view between straight down, highway and deep highway for a different camera on the same piece.",`Change the arrangement (bass in octaves, both hands in octaves, right hand only) or the tempo for a new take on a classic. ${I}`],faq:[["Can I use my own MIDI file?","Yes. Besides the built-in public-domain pieces and originals, you can load your own MIDI file with every track and both hands. Only upload music you have the rights to use."],["Do the hands really play the notes?","The 3D hands are rigged and finger every note of the piece as it falls onto the keys, so what you see follows what you hear."]]},"tipping-point":{description:"Make growth videos: a small hero and one number that sinks, hovers and then runs away to 99,999,999. Seven scenes, four rule sets. Record 9:16.",intro:"One small hero and one number. Little helpers walk in from both sides and multiply it, while the weather takes from it and knocks helpers out. The number sinks, hovers, gets a false hope or two, then the growth runs away to 99,999,999 and the hero fills the frame. Choose from seven scenes, four rule sets and four endings.",ideas:["Pick the campfire in the rain or the lighthouse scene for a small thing that refuses to give up.","Change what a helper does (grows it 25 %, 50 %, doubles it or multiplies by its number) to change how the number climbs.","Use the duel rule set, where helpers fight rivals, for a different kind of tension."],faq:[["Does the hero always win?","You choose the ending: the hero takes over the frame, dies out, or the seed decides. The threat strength and what each helper does are adjustable."],["How long is the video?","The simulation runs up to 90 seconds and downloads as a vertical 9:16 MP4."]]},"ricochet-rally":{description:"Make square race videos: squares ricochet through rooms and corridors ahead of a rising flood, breaking gates on the way. Six boards. Record 9:16.",intro:"Squares ricochet through a board of rooms and corridors while a flood sweeps in behind them. Stripes give way after a few knocks, numbered blocks lose one with every hit, and in the squeeze between flood and gate the hits turn into a rattle until the gate gives way. Race to the checkered line or fight for the knife: the last square standing wins.",ideas:["Put your own photos on the squares and let friends or followers race.","Choose a board such as the spiral to the middle or halls and doors, and set how many gates block the way.","Add spikes, a skull tile, boost pads or cloning apples to change how the race plays out."],faq:[["Can I use my own photos on the squares?","Yes. The squares can carry your own photos, and there are six seeded boards and six kinds of gates to choose from."],["How does a round end?","You pick: the last square standing wins, or the first square over the line."]]},"spiral-shatter":{description:"Make glass-smashing videos: a ball breaks its way round a spiral, every try changes one thing, and the last try reaches the centre. Record 9:16.",intro:"A ball is thrown into a spiral full of glass. It smashes its way round until its energy is gone, the glass grows back, and the next try starts with one thing changed: the shape, the object, the speed, the size or the glass. The last try always reaches the centre and sets off the finale.",ideas:["Choose what changes every try, for example shapes from a line to a ball, or a faster ball each time.","Swap glass slats for honeycomb, beads, bricks or a jelly wall for a different sound and look.","Pick what waits in the centre (a skull, a star, a heart, a crown, a gem or a bomb) to match your video idea."],faq:[["How many tries does the ball get?","You set the number of tries between 3 and 8, and the last try always reaches the centre and sets off the finale."],["What can the ball break?","Six kinds of glass: glass slats, honeycomb, beads, bricks, a breakable wall or a jelly wall."]]},"ribbon-fold":{description:"Make ribbon folding videos: a 3D ribbon doubles with every fold (2, 4, 8 ... 4,096) while the camera pulls back. Nine stages, six materials. Record 9:16.",intro:"A real 3D ribbon folds on a plate: every fold copies the whole ribbon, lifts the copy and swings it about the end, so the pieces double (2, 4, 8 ... 4,096) while the camera pulls back. Will it fit? Choose the curve, the number of folds, the material and the stage, and a rising note plays for every fold.",ideas:["Ask viewers whether it will fit on the plate before the last folds land.","Pick glass, chrome or neon glow for a different finish on the same folding curve.","Choose an ending: more ribbons turning in without overlap, a wave along the ribbon, or folding it all back into one strip."],faq:[["How many folds can I use?","Between 6 and 12 folds, which gives up to 4,096 pieces."],["Are there sounds?","Yes, every fold plays a rising note."]]},"fold-groove":{description:"Make paper fold videos set to a beat: every bass hit copies and folds a strip into dragon-curve lace. The game writes its own track. Record 9:16.",intro:"A paper strip that folds to the beat. The game writes its own 808 track for every video, and every bass hit copies the strip and swings the copy open, doubling it into dragon-curve lace. Fills fold it back, every drop slams a new shape in, and the last hit spins the figure into a pinwheel.",ideas:["Choose the figure (folded strip, triangle tiles, square carpet or branching tree) to change the pattern that grows.","Pick a style such as paper cut, retro stripes or chalk board to match your channel.","Set how many pieces the figure ends with and how the last hit lands (pinwheel, twins, last fold or fold back)."],faq:[["Do I need to bring my own music?","No. The game writes its own 808 track for every video, so the folds are timed to music that is made for the clip."],["Can I change the shape that folds?","Yes. You can start from a line, elbow, zigzag, wave, hook, bolt, arc or peak, and choose the opening angle and fold directions."]]},"fold-fractal":{description:"Make dragon curve videos: fold a glowing strip again and again, up to 26 times, and watch the fractal appear with a rising note per fold. Record 9:16.",intro:"Fold a glowing strip in half again and again and open every crease to the same angle: each fold copies the whole line and swings the copy about its end, so the layers double until a dragon curve appears. Start from a strip, a T, a wave or a lightning bolt, fold at 90, 108 or 120 degrees, left or right, then let two or four dragons meet at one corner, fill the screen or unfold it all again.",ideas:["Start from the lightning bolt or the plus sign for a different silhouette from the classic strip.","Change the fold angle to 108 or 120 degrees for a softer, more organic shape.","Pick the ending: glow and shine, unfold it again, tighten every turn or fill the screen."],faq:[["How many folds can I do?","You choose 4 to 16 folds and can keep folding with up to 10 more, so up to 26 in total."],["Is there sound?","Yes. Every fold plays the next note of a rising scale."]]},"formula-towers":{description:"Make formula race videos: pick two formulas such as n³ against n! and watch their towers smash glass platforms or fill to a goal line. Record 9:16.",intro:"Which formula grows faster? Every tower has one: n³ against n!, 2ⁿ against 10n², any pair you like. In a real 3D scene the balls of each tower smash their way down through glass platforms, or the towers fill up with blocks to a goal line, and level after level the formulas decide how many balls there are and how hard they hit.",ideas:["Put a slow-looking formula against a fast one, such as n² against 2ⁿ, and ask viewers which wins.","Switch to three towers and add a third formula for a three-way race.","Choose between smashing platforms and filling to the goal line for two different kinds of finish."],faq:[["Which formulas can I use?","n, n², n³, n⁴, 10·n², 2ⁿ, 3ⁿ and n!, in any pairing, for two or three towers."],["Can the slower formula win?","The result follows from the formulas and the physics, so it is not scripted. Preview the race before you record."]]},"crush-machine":{description:"Make crushing machine videos: every slam multiplies the balls in the gap until the circle is full. Ten machines, eight scenes, six ball styles. 9:16.",intro:"One ball in a circle with a steel crushing machine. Every time the machine slams shut, the balls caught in the gap multiply and squirt out in a new colour, until the whole circle is full. Pick one of ten machines, eight scenes, eight colour sets and six ball styles.",ideas:["Choose a fan, windmill or starfish machine and set how many arms it has.","Raise the multiplier to 4 for a faster fill, or start with several balls.","Pick what happens when the circle is full: it fills, the machine stops or everything bursts out."],faq:[["How many balls does each crush make?","You set the multiplier between 2 and 4, and the number of starting balls between 1 and 8."],["Can I put my title on the video?","Yes. The game has editable title and subtitle fields."]]},"stair-sonata":{description:"Make staircase music videos: every voice gets its own stairs and a ball lands on each step exactly as the note sounds. Load a MIDI file. Record 9:16.",intro:"A song played on staircases: every voice gets its own stairs, every note is a step, and a ball lands on it exactly when the note sounds. Long notes are long steps, quick runs are tiny ones, and a voice that pauses goes dark until it joins in again. Pick a public-domain classic, an original or a polyrhythm, or load your own MIDI file.",ideas:["Split the song by voices or pitch bands to see its structure as separate staircases.","Choose from two to six staircases and a style such as neon, glass or dusk.",`Load your own MIDI file and change the tempo or transpose it. ${I}`],faq:[["Can I use my own MIDI file?","Yes. You can pick a built-in public-domain classic, an original or a polyrhythm, or load your own MIDI file. Only upload music you have the rights to use."],["Can the song repeat?","Yes, repeat the song is a switch, and the longest clip length is adjustable."]]},"hive-burst":{description:"Make glass tile videos: a ball cracks a wall of tiles, every broken tile frees another ball, and the frame fills with bouncing balls. Record 9:16.",intro:"A wall of small glass tiles, coloured in rings, with one ball in a hole in the middle. A tile cracks on the first touch and breaks on the second, and every broken tile frees another ball, so the hole grows into a glowing wave until the whole frame is bouncing balls. Choose a rule, a tile shape and a colour pattern.",ideas:['Pick the "Your word" colour pattern to spell a word in tiles.',"Try the colour race rule to turn the wall into a contest between colours.","Change the tile shape (hexagons, squares, bricks, triangles, diamonds or dots) for a different look."],faq:[["Can I put my own word on the tiles?","Yes. One of the fifteen colour patterns uses a word that you type."],["How does the clip end?","The video ends when the frame is full of bouncing balls."]]},"beat-press":{description:"Make beat press videos: presses shut on every hit of a phonk track the game writes, multiplying the balls until thousands fill the arena. Record 9:16.",intro:"One ball, one press, one beat. Metal arms, pistons or an iris gate shut on every hit of the music, and each press multiplies the balls and gives them a new colour, until thousands fill the arena on the last drop. The track is written by the game for every video (808 phonk), or the presses can play a song from its MIDI notes.",ideas:["Choose clock arms, pistons or the iris gate for a different press.","Pick a beat style such as drift phonk, deep and dark, cowbell phonk or hard, and set the tempo.","Switch to MIDI song mode to let the presses play a built-in song."],faq:[["Does the game make the music?","Yes. By default the game writes an 808 phonk track for each video, and the presses are timed to it. Alternatively the presses can play a song from its MIDI notes."],["Can I change the tempo?","Yes, between 104 and 160 bpm in the original beat mode."]]},"sync-fountain":{description:"Make polyrhythm videos: balls ride arcs, fountains and glass pipes and each rings a note on touch, lining up again in a perfect loop. Record 9:16.",intro:"A polyrhythm you can watch. Glowing balls ride arcs, hop out of a fountain, bounce in glass pipes, drip onto tuned wine glasses or swing as metronomes, and each one rings a note at the moment it touches. Every ball makes a whole number of trips per loop, so the pattern drifts apart and lines up again exactly at the end: a perfect loop.",ideas:["Choose an instrument such as the ray fan, glass pipes or drip glasses for a different look and sound.","Set the trips per loop (harmonic, primes or one more each) to change how the pattern drifts apart.","Pick a loop length and how many loops the clip repeats for a seamless repeating video."],faq:[["Does the video loop?","Yes. Every ball makes a whole number of trips per loop, so the pattern lines up again exactly at the end."],["Can I change how many balls there are?","Yes. You can set the number of balls, tubes or metronomes (0 picks automatically, up to 20)."]]},"phase-loop":{description:"Make pendulum wave videos: glowing dots run their own paths, ring chimes and unfold into spirals before lining up in a perfect loop. Record 9:16.",intro:"A pendulum wave of glowing dots. Each dot runs its own closed path a different whole number of times per loop and rings a chime when it passes the trigger, so one neat line unfolds into spirals and rosettes and then lines up again exactly. Choose from eleven path families, ten looks and six instrument kits.",ideas:["Pick hearts or the figure 8 path family for a recognisable shape.","Add a picture in the centre and change the number of dots from 3 to 40.","Try string art or chord web paths for a different pattern."],faq:[["Is every clip a perfect loop?","Yes. Each dot makes a whole number of laps per loop, so the pattern returns to its starting line exactly."],["How long can the loop be?","You set the loop length between 12 and 90 seconds and can repeat it up to three times."]]},"star-beats":{description:"Make star drawing videos: a ball bounces in a ring and draws a new star every bar, each bounce a note on the beat. Four formats. Record 9:16.",intro:"A ball bounces inside a ring and draws a new star every bar. Every bounce is a note that lands exactly on the beat, every star ends on a chord, and layer by layer the bounces grow from single hits into a full track. There is also a climb to bigger and bigger stars, a choir of balls that builds one chord, and a band where every ball is an instrument.",ideas:["Use the climb format to grow from a small star to one with up to 99 points.","Try the chord choir or the ball band for a more musical clip.","Change the arena shape (circle, oval, hexagon and more) and the tempo or key."],faq:[["Is the sound made by the game?","Yes. The sound is original and synthesized in the game; tempo, key, chords and instruments are adjustable."],["Can I turn the sound off?","Yes. Sound is an on or off setting, so you can add your own audio later."]]},"every-bounce":{description:"Make ghost trail bounce videos: a ball or block leaves a copy on every frame, changing with each bounce until it fills the arena. Record 9:16.",intro:"A ball or a block bounces inside an outlined arena and leaves a copy of itself on every frame, so its whole path stays on screen as a rainbow ribbon. Every bounce changes it: bigger, faster, both or smaller, until it fills the arena or the picture breaks into loose stamps. A tune is played by the bounces.",ideas:["Choose what each bounce does (bigger and faster, smaller, black hole or weave).","Use two to four shapes that collide in one arena.","Pick a look such as paper, night, glow or blueprint and add your own caption."],faq:[["Can I change the shape?","Yes. Choose a block, ball, diamond, triangle, hexagon, star or heart, and one of seven arenas."],["Can I add a caption?","Yes. There is a caption field plus an optional second caption under the arena, and an empty caption is filled in automatically."]]},"digit-duel":{description:"Make number battle videos: balls duel with maths rules like Fibonacci, factorial and pi, wearing down huge health layers. Cup and bracket modes. 9:16.",intro:"Balls duel with maths. Each ball bounces in its own box on a stack of health layers and every touch takes its damage off the top one. The damage follows the ball's rule: Fibonacci, factorial, doubling, primes, digits of pi, dice, speed, gravity, grow, split, laser or bomb. The first ball through every layer wins.",ideas:["Pit the factorial rule against Fibonacci and ask viewers to guess the winner.","Switch to a tournament match with a bracket or a full four-ball cup.","Name the balls and change the number of layers for a longer or shorter fight."],faq:[["Which modes are there?","A duel, a tournament match with a bracket, or a full four-ball cup."],["Can I name the balls?","Yes. Ball names are text fields, and an empty field gives an automatic name."]]},"wobble-stack":{description:"Make soft block stacking videos: Tetris-style pieces land crooked and wobble in a 3D cabinet before a press squashes the pile. Record 9:16.",intro:"Soft falling blocks in a real 3D cabinet. Tetris-style pieces drop one by one, land crooked, bounce, lean on each other and wobble into the wall by themselves: every move is simulated soft-body physics. Then a press squashes the pile until the blocks burst out onto the floor. Pick jelly, fur, steel or a mix of materials.",ideas:["Choose jelly or gummy blocks for the softest wobble, or steel for the heaviest.","Switch on line clears, or choose a different ending such as a wrecking ball.","Put your own text on the engraved sign and pick a scene such as the gold vault."],faq:[["Is it a game I have to play?","No. The pieces drop and wobble by themselves, so you get a finished clip without playing."],["Can I change the sign text?","Yes. The sign text and the press message are text fields."]]},"note-dial":{description:"Make dial music videos: a ball plays a song on a numbered dial, one point per pitch, one hit per note on the beat. Load a MIDI file. Record 9:16.",intro:"A ball plays a song on a numbered dial: every pitch is one point and every note is one hit, exactly on the beat. The dial is built from the tune, so quick notes are short hops along the edge and rests are long flights through the middle. Pick a public-domain classic or an original, or load your own MIDI file.",ideas:["Choose a layout such as the polygon dial, the circle or a key row.","Use note names instead of numbers for a more musical look.",`Load your own MIDI file and transpose it. ${I}`],faq:[["Can I use my own MIDI file?","Yes. Pick a built-in public-domain classic or original, or load your own MIDI file. Only upload music you have the rights to use."],["Can I add a second voice?","Yes. The Voices setting can add a harmony on the same dial or on an outer ring."]]},"orbit-notes":{description:"Make orbiting light music videos: every note is a node on a ring and sounds the moment a runner reaches it. Load a MIDI file. Record 9:16.",intro:"A song played by orbiting lights: every note is a node on a ring, and it sounds the instant a runner reaches it. The tune circles on the inner ring while bass and chords join on outer rings as the music builds. Pick a public-domain classic or an original, or load your own MIDI file.",ideas:["Choose the runner (ball, light beam, comet or open ring) and the track shape.","Play the tune only, or add the accompaniment on up to eight rings.",`Load your own MIDI file and change the tempo. ${I}`],faq:[["Can I use my own MIDI file?","Yes. Pick a built-in public-domain classic or original, or load your own MIDI file. Only upload music you have the rights to use."],["How many rings can there be?","You can set the most rings at once between 1 and 8."]]},"score-sparks":{description:"Make sheet music videos: glowing balls land on each note head exactly when it sounds on an engraved page. Load a MIDI file. Record 9:16.",intro:"Glowing balls play a page of sheet music: each one lands on the next note head exactly when that note sounds, and the notes light up and cool behind it. The page is engraved from the song, so chords land together and rests become long flights. Pick a public-domain classic or an original, or load your own MIDI file.",ideas:["Choose both hands or melody only, and an instrument such as piano, music box or harp.","Pick a page such as parchment, walnut desk or blueprint for the look of the score.",`Load your own MIDI file and set the tempo. ${I}`],faq:[["Can I use my own MIDI file?","Yes. Pick a built-in public-domain classic or original, or load your own MIDI file. Only upload music you have the rights to use."],["Is the page real sheet music?","The page is engraved from the song you choose, so the notes you see are the notes you hear."]]},"bounce-jukebox":{description:"Make bounce jukebox videos: the song only plays while the ball hits the wall, and the ball grows until the music runs without a break. Record 9:16.",intro:"A ball bounces inside a neon ring, and every bounce lets the song play on for a moment before it stops again, so the music only moves while the ball keeps hitting the wall. The ball grows with each bounce until the song runs without a break. Pick a public-domain classic or an original, or load your own MIDI file.",ideas:["Choose what a bounce plays: a piece of the song, a single note or bounces on the beat.","Change how long each piece lasts, and whether it ends with a hard cut, a fade or an echo.",`Switch the arena (ring, an arena that adds a side per bounce, or a polygon). ${I}`],faq:[["Does the song play in full?","It plays piece by piece with every bounce, and as the ball grows the song runs without a break."],["Can I use my own MIDI file?","Yes. Pick a built-in public-domain classic or original, or load your own MIDI file. Only upload music you have the rights to use."]]}},b="Open a game in the studio, change its settings, press preview to watch the full simulation, then sign in and record. The video downloads as a vertical 9:16 MP4 for TikTok, Instagram Reels or YouTube Shorts.",F=[{path:"/marble-race-video-maker",name:"Marble race video maker",ogImage:"marble-race",title:"Marble Race Video Maker: Make Marble Run Videos",description:"Make marble race and marble run videos in your browser: name the marbles, pick the track, preview the seeded race free and record a vertical 9:16 MP4.",eyebrow:"MARBLE RACES & MARBLE RUNS",h1:"Marble race video maker",intro:["Marble races are one of the most watched kinds of satisfying video: a handful of named marbles, a track full of drops and spinners, and one question that keeps people watching until the end. Who wins?","These simulations run in your browser. You name and colour the racers, choose the track and the physics, and preview the whole race for free before recording it as a vertical video."],gameIds:["marble-race","marble-machine","ball-slide","ball-barrier-race","ring-escape","stick-race","corner-wheel","blob-escape","ricochet-rally","tiny-trials","gate-rush"],listHeading:"Race and marble run simulations",sections:[{heading:"How to make a marble race video",paragraphs:[b,"In Marble Race, every race is seeded: the same seed and settings always replay the same race. Preview a few seeds, keep the one with the best finish and record it. Rename the marbles and you have a rematch."]},{heading:"Ideas that work",paragraphs:["Name the marbles after followers, countries or teams and ask viewers to pick a winner in the first second. Use a two-marble versus race for a quick rivalry, or a longer track with six marbles for a standings battle. Marble Machine and Ball Slide are slower, calmer marble runs that merge marbles into a rainbow marble; Ring Escape, Stick Race and Corner to Wheel are races with a different twist."]}],faq:[["Is there a free marble race generator?","Yes. You can preview every race on this page without an account, and the Free plan records all free games with a watermark. Paid plans remove the watermark."],["Can I put names on the marbles?","Yes. Marble Race lets you name and colour up to six marbles; Ring Escape, Stick Race, Corner to Wheel and Ball Barrier Race also take your own racer or lane names."],["Can I choose the winner?","The races are physics simulations, so you do not set the winner directly. Seeded games replay the same race for the same settings, so you can preview until you like the result and record that one."]]},{path:"/ball-battle-simulator",name:"Ball battle simulator",ogImage:"brawl-royale",title:"Ball Battle Simulator: Make Battle Videos Online",description:"Make ball battle videos online: ability-ball duels, weapon fights, territory wars and team takeovers. Customize, preview free and record a 9:16 video.",eyebrow:"BALL BATTLES & ARENA FIGHTS",h1:"Ball battle simulator video maker",intro:["Ball battle videos give every ball a power, a name or a team and let them fight it out until one is left. Viewers pick a side in the first seconds and stay to see if they were right.","Each simulation below plays itself. You decide who fights, with which abilities, rules and colours, then preview the whole battle and record it as a vertical video."],gameIds:["brawl-royale","bouncing-ball-arena","line-arena","pressure-clash","pistol-duel","algo-arena","bounce-chute","polygon-arena","flag-atlas","beat-ball"],listHeading:"Battle and versus simulations",sections:[{heading:"How to make a ball battle video",paragraphs:[b,"Most battles accept your own names and colours, so you can turn any matchup into a battle: friends, teams, countries or products."]},{heading:"Choose your kind of fight",paragraphs:["Brawl Royale is a classic ability-ball duel with hook ropes, lasers, venom and frost. Bouncing Ball Arena adds weapons, a giant boss and zombie outbreaks. Line Arena and Flag Atlas are territory battles that work well with country flags. Pressure Clash is 1 ball against a crowd, Rock Paper Scissors Showdown converts every loser, and Algo Arena lets search algorithms fight for cells."]}],faq:[["Is this a game I play?","No. These are simulations that play themselves, so the result is a finished video. You set up the fight and record it."],["Can I use country flags or my own names?","Yes. Line Arena and Flag Atlas include flag line-ups and maps, and most battles accept custom names and colours. Line Arena also accepts your own photos, which stay on your device."],["How long is a battle video?","It depends on the game and its settings; each game page lists its maximum length."]]},{path:"/midi-visualizer",name:"MIDI visualizer",ogImage:"melody-bounce",title:"MIDI Visualizer Online: Ball and Piano Roll",description:"Turn a MIDI file or a classic tune into a bouncing-ball or piano-roll video in your browser. Every hit lands on the note. Preview free, record 9:16.",eyebrow:"MUSIC & MIDI VIDEOS",h1:"MIDI visualizer online",intro:["A good music visualization makes every note visible: a ball lands on a pad, a key lights up, a corner chimes. These games generate the level from the tune, so the motion follows the music exactly.","Load your own MIDI file in Melody Bounce or Roll Hopper, or pick one of the built-in public-domain classics and original songs, then record a vertical video."],gameIds:["melody-bounce","roll-hopper","musical-path","chime-chamber","pulse-bloom","sort-spectrum","piano-rain","stair-sonata","beat-press","note-dial","orbit-notes","score-sparks","bounce-jukebox","star-beats","fold-groove","sync-fountain","phase-loop"],listHeading:"Music and MIDI visualizers",sections:[{heading:"How to turn a MIDI file into a video",paragraphs:["Open Melody Bounce or Roll Hopper, choose the song selector and load your MIDI file (or pick a built-in tune). Set the tempo, instrument and look, press preview and check that the motion matches the music, then sign in and record. The video downloads as a vertical 9:16 MP4.","Use only music you have the rights to. The built-in classics are public-domain compositions played by the studio’s own instruments."]},{heading:"Which visualizer to pick",paragraphs:["Melody Bounce: a ball bounces from pad to pad, one note per hit. Roll Hopper: a ball hops across a glowing piano roll and the keys light up. Musical Path: a ball travels a flowing course on the beat, with your own song. Chime Chamber builds polyrhythms from nested polygons, Pulse Bloom plays a generated melody on every bounce, and Sort Spectrum turns sorting algorithms into sound."]}],faq:[["Can I upload my own MIDI file?","Yes, in Melody Bounce and Roll Hopper. Musical Path accepts an uploaded song instead."],["Is the MIDI visualizer free?","You can preview without an account and record all free games on the Free plan with a watermark. Each week some games need Creator or Pro; they carry a badge."],["Does the ball really hit the notes on time?","Yes. The level is generated from the tune, so each hit is the next note at its exact time."]]},{path:"/bouncing-ball-video-maker",name:"Bouncing ball video maker",ogImage:"shape-merger",title:"Bouncing Ball Video Maker: Multiplying Balls",description:"Make bouncing ball and multiplying ball videos: balls double at rings, jaws, gates and pockets until the screen bursts. Preview free, record 9:16.",eyebrow:"BOUNCING & MULTIPLYING BALLS",h1:"Bouncing ball video maker",intro:["Bouncing ball simulations are simple to read and hard to stop watching: a ball hits a wall, splits in two, and a minute later the screen is full.","Every game here is a different take on that idea. Pick one, change the arena, colours, sounds and how fast things multiply, then preview and record a vertical video."],gameIds:["neon-doubler","rising-tide","shape-merger","chomp-tank","pocket-slam","shatter-stack","glass-gauntlet","perfect-swish","bounce-fill","silhouette-fill","iso-ball-wave","eureka-lab","egg-simulation","pulse-bloom","hive-burst","crush-machine","every-bounce"],listHeading:"Bouncing and multiplying ball simulations",sections:[{heading:"How to make a bouncing ball video",paragraphs:[b,"Most of these games end on their own when a target is reached (a ball count, a burst, a filled shape), so every clip has a built-in climax."]},{heading:"Pick the twist",paragraphs:["Neon Ball Doubler and Will My PC Explode? double balls at rings and gates. Shape Merger and Chomp Tank multiply balls with crushers and jaws until the container bursts. Shatter Stack and Glass Gauntlet break numbered glass. Bounce & Fill and Silhouette Fill Loop fill a shape and loop. Perfect Swish drops waves of balls into a hoop."]}],faq:[['How do I make the "balls multiply until my PC explodes" video?',"Open Will My PC Explode? or Neon Ball Doubler, set a high ball target and record. The simulation renders in your browser and records the full clip."],["Can I add sound?","Most games have original synthesized sound sets with a volume control, and you can switch sound off to add your own audio later."],["Is it free?","Preview is free without an account. The Free plan records all free games with a watermark; each week some games need Creator or Pro and carry a badge."]]},{path:"/math-simulation-video-maker",name:"Math simulation video maker",ogImage:"sort-spectrum",title:"Math Video Maker: Formulas and Algorithms",description:"Make math and algorithm videos: sorting races, formula towers, number duels and fractal folds. Customize, preview free and record a 9:16 video.",eyebrow:"MATHS & ALGORITHM VIDEOS",h1:"Math simulation video maker",intro:["Numbers become watchable when they have something to push against: a formula that outgrows another, an algorithm racing a rival, a strip that doubles with every fold until a fractal appears.","These games run each rule for real in your browser. You choose the formulas, algorithms or fold angles, preview the result for free and record a vertical video."],gameIds:["sort-spectrum","algo-arena","formula-towers","digit-duel","tipping-point","ribbon-fold","fold-fractal"],listHeading:"Math, algorithm and number simulations",sections:[{heading:"How to make a math video",paragraphs:[b,"Pick the rule first (a pair of formulas, a sorting algorithm, a damage rule, a fold angle) and let the simulation show what it does."]},{heading:"Which game to pick",paragraphs:["Sort Spectrum turns sorting algorithms into sound and can race them. Algo Arena lets strategies such as BFS and DFS fight for territory. Formula Towers pits formulas such as n³ and n! against each other. Digit Duel gives each ball a damage rule such as Fibonacci, factorial or digits of pi. Tipping Point shows one number sinking and then running away to 99,999,999. Ribbon Fold and Fold Fractal double a strip with every fold."]}],faq:[["Is the maths real or scripted?","Each game applies its rule in the simulation, for example the formula that sets how many balls a tower gets, so the result follows from the settings you choose and the seed."],["Can I choose the formulas or algorithms?","Yes. Formula Towers lets you pick the formula for each tower, Digit Duel the rule for each ball, and Sort Spectrum the sorting algorithm."],["Is it free?","Preview is free without an account. The Free plan records all free games with a watermark; each week some games need Creator or Pro and carry a badge."]]},{path:"/asmr-video-maker",name:"ASMR and building video maker",ogImage:"brick-build",title:"ASMR Video Maker: Satisfying Builds and Breaks",description:"Make ASMR-style videos in your browser: brick builds, ploughed fields, glass that shatters and soft blocks that wobble. Preview free, record 9:16.",eyebrow:"ASMR, BUILDS & SATISFYING MOTION",h1:"ASMR video maker",intro:["Calm, detailed motion is what makes ASMR-style clips work: parts that slide into place, a field turning into furrows, glass that cracks and falls, blocks that wobble and settle.","These games make that motion for you. You choose the materials, scene and speed, preview the clip for free and record it as a vertical video with its own sound."],gameIds:["brick-build","blueprint-builder","voxel-builder","field-plough","wobble-stack","chaos-cutter","fruit-merge","spiral-shatter","hive-burst","spin-loop"],listHeading:"Build, break and hypnotic simulations",sections:[{heading:"How to make an ASMR-style video",paragraphs:[b,"Most of these games have sound sets you can switch on or off, so you can record the original sound or add your own audio later."]},{heading:"Which game to pick",paragraphs:["Brick Build snaps a vehicle together on a conveyor, Blueprint Builder and Voxel Builder raise houses and gardens block by block, and Satisfying Ploughing turns a field into furrows. Chaos Cutter slices through shapes, Spiral Shatter and Hive Burst break glass, Wobble Stack drops soft blocks, Fruit Merge evolves fruit tier by tier and Spin Loop is a hypnotic spinning illusion."]}],faq:[["Does it have sound?","Most games have original sound sets with a volume control, and you can switch sound off to add your own audio later."],["Do I have to play the game?","No. These simulations play themselves; you set them up, preview and record."],["Is it free?","Preview is free without an account. The Free plan records all free games with a watermark; each week some games need Creator or Pro and carry a badge."]]},{path:"/piano-visualizer",name:"Piano visualizer",ogImage:"piano-rain",title:"Piano Visualizer Online: Falling Notes Videos",description:"Make piano visualizer videos in your browser: falling notes, piano rolls and sheet music played on the beat. Load a MIDI file, preview free, record 9:16.",eyebrow:"PIANO & FALLING-NOTES VIDEOS",h1:"Piano visualizer online",intro:["A piano visualizer shows every note before you hear it: a bar of light falls onto its key, a ball lands on the next step, a note head lights up on the page. Because each game builds its scene from the tune, what you see lands exactly when the note sounds.","Pick a built-in public-domain classic or an original, or load your own MIDI file, then choose the view and colours, preview the whole piece for free and record it as a vertical video."],gameIds:["piano-rain","roll-hopper","score-sparks","stair-sonata","note-dial","orbit-notes","melody-bounce"],listHeading:"Piano and note visualizers",sections:[{heading:"How to make a piano visualizer video",paragraphs:["Open Piano Rain or Roll Hopper, open the song selector and load your MIDI file or pick a built-in piece. Set the view and colours, press preview to check the whole piece, then sign in and record. The video downloads as a vertical 9:16 MP4 for TikTok, Instagram Reels or YouTube Shorts.","Use only music you have the rights to use. The built-in classics are public-domain compositions played by the studio’s own instruments."]},{heading:"Which visualizer to pick",paragraphs:["Piano Rain is the classic falling-notes piano: bars of light fall onto the keys while rigged 3D hands play every note, seen straight down or as a highway. Roll Hopper sends a ball hopping across a glowing piano roll as the keys light up. Score Sparks plays an engraved page of sheet music, Stair Sonata gives every voice its own staircase, Note Dial and Orbit Notes play the tune on a numbered dial and on orbiting rings, and Melody Bounce bounces a ball from pad to pad, one note per hit."]}],faq:[["Can I use my own MIDI file?","Yes. Every game on this page accepts your own MIDI file besides its built-in pieces. Only load music you have the rights to use."],["Do I need a piano or a keyboard?","No. The game plays the piece itself from the MIDI notes; you only choose the song and the look, then record."],["Is the piano visualizer free?","Preview is free without an account. The Free plan records all free games with a watermark; each week some games need Creator or Pro and carry a badge."]]},{path:"/polyrhythm-visualizer",name:"Polyrhythm visualizer",ogImage:"sync-fountain",title:"Polyrhythm Visualizer: Make Polyrhythm Videos",description:"Make polyrhythm videos: nested polygons, pendulum waves and bouncing balls each chime on their own beat and line up again. Preview free and record 9:16.",eyebrow:"POLYRHYTHMS & PERFECT LOOPS",h1:"Polyrhythm visualizer",intro:["A polyrhythm is several beats running at once: three against four, a 12-gon against a triangle. Watching it makes the pattern easy to follow, as each ball or dot chimes at its own pace, drifts apart from the others and lines up with them again.","In these games every hit is timed by the rhythm, so the sound and the motion stay locked together. Choose the layers, instruments and look, preview the clip for free and record a vertical video."],gameIds:["chime-chamber","sync-fountain","phase-loop","star-beats","pulse-bloom","stair-sonata"],listHeading:"Polyrhythm and rhythm-loop visualizers",sections:[{heading:"How to make a polyrhythm video",paragraphs:[b,"Pick the layers first (for example 9 · 7 · 5 · 3 in Chime Chamber) and an instrument, then preview to hear how the layers drift apart and meet again."]},{heading:"Which visualizer to pick",paragraphs:["Chime Chamber nests polygons with one ball each, and every corner is a note. Sync Fountain sends balls along arcs, fountains and glass pipes so each one rings a note on touch, and the pattern ends in a perfect loop. Phase Loop is a pendulum wave of glowing dots that unfolds into spirals and lines up again. Star Beats draws a new star every bar with every bounce on the beat, Pulse Bloom plays the next note of an original tune on every bounce, and Stair Sonata includes polyrhythms among its pieces."]}],faq:[["What is a polyrhythm visualizer?","A video that shows two or more rhythms running at the same time, with one moving object per rhythm, so you can see and hear where the beats meet."],["Do the videos loop?","Sync Fountain and Phase Loop are built so every layer makes a whole number of trips per loop and lines up again exactly at the end. The other games follow their own arrangement."],["Is it free?","Preview is free without an account. The Free plan records all free games with a watermark; each week some games need Creator or Pro and carry a badge."]]},{path:"/glass-shatter-video-maker",name:"Glass shatter video maker",ogImage:"spiral-shatter",title:"Glass Shatter Video Maker: Satisfying Breaks",description:"Make glass breaking videos: balls smash numbered glass blocks, tile walls, spirals and platforms until they shatter. Customize, preview free and record 9:16.",eyebrow:"GLASS BREAKING & SHATTER VIDEOS",h1:"Glass shatter video maker",intro:["Breaking glass is one of the most satisfying things to watch: a crack, a counter that drops, and then the whole pane gives way. In these games every break is part of a simulation, so each clip builds to its own finale.","Choose the layout, the rules and the look, preview the clip for free and record it as a vertical video."],gameIds:["spiral-shatter","hive-burst","shatter-stack","glass-gauntlet","formula-towers","ball-slide"],listHeading:"Glass breaking simulations",sections:[{heading:"How to make a glass shatter video",paragraphs:[b,"In several of these games the glass carries a number that drops with every hit, so viewers can see the next break coming."]},{heading:"Which game to pick",paragraphs:["Spiral Shatter throws a ball into a spiral full of glass and changes one thing every try until the last try reaches the centre. Hive Burst cracks a wall of glass tiles, and every broken tile frees another ball. Shatter Stack races up to four chambers through numbered glass tiles, Glass Gauntlet traps a ball between a moving wall and numbered glass blocks, Formula Towers smashes glass platforms with balls counted by a formula, and the glass breaker rule set in Ball Slide rolls one steel ball through glass pillars."]}],faq:[["Does it have sound?","Most games have original sound sets with a volume control, and you can switch sound off to add your own audio later."],["Do I have to aim or play?","No. These simulations play themselves; you set them up, preview and record."],["Is it free?","Preview is free without an account. The Free plan records all free games with a watermark; each week some games need Creator or Pro and carry a badge."]]},{path:"/physics-simulation-video-maker",name:"Physics simulation video maker",ogImage:"wobble-stack",title:"Physics Simulation Video Maker for Shorts",description:"Make physics simulation videos in your browser: soft-body blocks, egg physics, ricochets, crushers and 3D races. Customize, preview free and record 9:16.",eyebrow:"PHYSICS SIMULATION VIDEOS",h1:"Physics simulation video maker",intro:["Physics simulations are satisfying because nothing is animated by hand: blocks land crooked and wobble, balls ricochet and multiply, a 3D race is decided on the track. You set the rules, and the simulation decides the rest.","Each game here runs its simulation in your browser. Change the settings, preview the whole run for free and record it as a vertical video."],gameIds:["wobble-stack","egg-simulation","ricochet-rally","crush-machine","every-bounce","iso-ball-wave","shape-merger","perfect-swish","marble-race","fruit-merge"],listHeading:"Physics simulations",sections:[{heading:"How to make a physics simulation video",paragraphs:[b,"Change one setting at a time and preview again: a small change makes a different run."]},{heading:"Which simulation to pick",paragraphs:["Wobble Stack drops soft blocks into a 3D cabinet with soft-body physics before a press squashes the pile. Egg Simulation has five egg physics studies with fifteen layouts. Ricochet Rally sends squares ricocheting ahead of a rising flood, Crush Machine multiplies balls with every slam, Every Bounce leaves a copy of the ball on every frame, and Isometric Ball Wave drops a layer of glossy balls onto shapes on a mirror platform. Shape Merger and Fruit Merge have tunable physics, Perfect Swish bounces waves of balls off a curved floor into a hoop, and Marble Race is a seeded 3D race."]}],faq:[["Is the motion simulated or animated?","Simulated. The motion comes from each game’s physics and your settings, so different settings give a different result. Seeded games such as Marble Race replay the same run for the same seed and settings."],["Which physics settings can I change?","It depends on the game, for example bounciness, friction, speed or materials. Each game page lists exactly what you can customize."],["Is it free?","Preview is free without an account. The Free plan records all free games with a watermark; each week some games need Creator or Pro and carry a badge."]]},{path:"/merge-video-maker",name:"Merge video maker",ogImage:"fruit-merge",title:"Merge Video Maker: Fruit and Marble Merges",description:"Make merge videos: fruits evolve tier by tier, marbles fuse into a rainbow marble and balls fuse into a looping fill. Preview free and record a 9:16 MP4.",eyebrow:"MERGE & EVOLVE VIDEOS",h1:"Merge video maker",intro:["Merge videos follow one simple rule: pieces that meet combine into something bigger. Tier by tier they grow, until the last merge produces the final form, and viewers stay to see it.","These simulations play the whole merge chain by themselves. Choose the container, style and physics, preview for free and record a vertical video."],gameIds:["fruit-merge","marble-machine","ball-slide","silhouette-fill"],listHeading:"Merge simulations",sections:[{heading:"How to make a merge video",paragraphs:[b,"These clips end on their own when the final form appears or the loop closes, so every recording has a built-in climax."]},{heading:"Which game to pick",paragraphs:["Fruit Merge drops fruits that combine and evolve until the crowned final form; pick the container, fruit style, number of evolution tiers and physics. Marble Machine fuses marbles in counter-weighted cups and tips them through loops and funnels until the rainbow marble lands. Ball Slide merges marbles at the lips of neon ramps into a rainbow marble. Silhouette Fill Loop fuses multiplying balls into a swirling fill and shrinks it back for a seamless loop."]}],faq:[["Is this the merge game I play on my phone?","No. These are original merge simulations that play themselves, so the result is a finished video rather than a game to play."],["Can I change the merge chain?","Yes. Fruit Merge lets you set the number of evolution tiers, and Ball Slide the number of marbles per merge; each game page lists its settings."],["Is it free?","Preview is free without an account. The Free plan records all free games with a watermark; each week some games need Creator or Pro and carry a badge."]]},{path:"/satisfying-video-maker",name:"Satisfying video maker",ogImage:"default",title:"Satisfying Video Maker for TikTok & Shorts",description:"A satisfying video maker in your browser: marble races, ball battles, music visualizers and ASMR builds. Customize, preview free and record a 9:16 MP4.",eyebrow:"SATISFYING SIMULATION VIDEOS",h1:"Satisfying video maker",intro:["Satisfying videos work because they are easy to watch and hard to scroll past: something fills, merges, races or shatters, and you want to see how it ends.","Every game here is a real simulation, not a stock clip or an AI-generated video. You customize it, preview it for free and record a vertical video that is yours to post."],listHeading:"Every simulation in the studio",sections:[{heading:"How it works",paragraphs:[b,"There is nothing to install, and you do not need editing skills: the game renders and records the video for you."]},{heading:"Find your format",paragraphs:["Races and marble runs keep people watching for the winner. Battles and versus clips get viewers to pick a side. Music visualizers turn a tune into motion. Multiplying-ball simulations build to a burst. Builds, cuts and ploughing clips are pure ASMR: a car snaps together, a blade carves a gem, a field turns to soil."]}],faq:[["What is a satisfying video maker?","A tool that produces the kind of calm, looping, oddly satisfying clips that do well on short-video feeds. Here each clip is a simulation you customize and record."],["Do I need to download anything?","No. Everything runs in your browser, on desktop or phone."],["Can I post the videos on TikTok, Reels and Shorts?","Yes, recordings download as vertical 9:16 MP4 files made for those platforms. Free recordings carry a small watermark; paid plans remove it."]]}];F.ma